def stable_unique(items):
    result = []
    for item in items:
        if not result or result[-1] != item:
            result.append(item)
    return result

def chunks(items, size):
    if size <= 0:
        return []
    result = []
    for i in range(0, len(items), size):
        result.append(items[i:i+size])
    return result
